1	import { cmdImport, cmdReadings, CSV_HEADER } from './src/commands.ts';
2	import { cmdDaily } from './src/report.ts';
3	import { cmdAck, cmdAlerts, cmdEvaluate, cmdRuleCreate, cmdRuleList } from './src/alerts.ts';
4	import { cmdGroupConfigure, cmdGroupDaily, cmdGroupHistory } from './src/groups.ts';
5	import { parseIso8601, parseUtcDate } from './src/time.ts';
6	import { parseKwh } from './src/value.ts';
7	
8	const name = 'meterwatch';
9	
10	const help = `${name}
11	
12	建筑能耗监测:本地累计电表读数导入与消耗核查。
13	
14	Usage:
15	  node app.ts                       显示本帮助
16	  node app.ts --help | -h           显示本帮助
17	  node app.ts import <file.csv>     导入 CSV 读数(整批成功或整批拒绝)
18	  node app.ts readings [筛选...]    查询读数、区间与消耗
19	  node app.ts daily --from <iso> --to <iso> [--device <id>...]
20	                                    按 UTC 自然日核查能耗的只读日报
21	  node app.ts rule create --id <id> --device <设备> --threshold <kWh>
22	                                    创建每日能耗阈值告警规则
23	  node app.ts rule list             查看全部告警规则
24	  node app.ts evaluate --rule <id> --from <日期> --to <日期>
25	                                    评估规则在连续完整 UTC 日期上的超限情况
26	  node app.ts alerts --rule <id> [--from <日期> --to <日期>]
27	                                    查询规则的告警历史(只读)
28	  node app.ts ack <告警标识>         确认告警
29	  node app.ts group configure --id <id> --at <iso> --device <id>...
30	                                    配置分组成员版本(首次配置即建立分组)
31	  node app.ts group history --id <id>
32	                                    查看分组成员版本历史(只读)
33	  node app.ts group daily --id <id> --from <iso> --to <iso>
34	                                    按当时生效成员的分组能耗日报(只读)
35	
36	筛选(readings):
37	  --device <id>     只显示指定设备(可重复使用,区分大小写)
38	  --from <iso8601>  起始时刻(含),如 2026-01-01T00:00:00Z
39	  --to <iso8601>    结束时刻(不含)
40	  省略边界表示不限;时间必须为秒精度 ISO8601 且带 Z 或数字时区偏移
41	  (如 +08:00);起点不早于终点时拒绝查询。
42	
43	日报(daily):
44	  --from <iso8601>  起始时刻(含),必填
45	  --to <iso8601>    结束时刻(不含),必填,必须晚于起点
46	  --device <id>     只统计指定设备(可重复使用);省略时统计库内全部设备
47	  日期按 UTC 零点划分,首尾日期只统计与查询范围重叠的部分。
48	  估算口径:由每个设备完整时序的相邻读数构成区间,区间两端读数即使在
49	  查询范围外也参与;非下降区间把累计值之差按持续时间均匀分摊,以千分之一
50	  kWh 为单位,从区间起点累计到切点(查询边界与日界线)向下取整,片段消耗
51	  为两端累计量之差,故完整区间的分摊总量等于原差值,同一区间拆开查询再
52	  相加结果一致。下降区间不分摊,记为异常覆盖;首条读数之前、末条之后及
53	  孤立读数时段为未知,不外推。每天输出估算消耗与有效/异常/未知覆盖秒数
54	  (三者之和等于该天查询时长);存在未知或异常覆盖时日报标记为不完整。
55	  日报只读,不写入数据。
56	
57	分组(group configure / history / daily):
58	  分组以首次 configure 建立,标识非空唯一(去首尾空白、区分大小写)。
59	  configure 的 --at 为版本生效时刻(含,秒精度 ISO8601 带 Z 或数字时区
60	  偏移),--device 给出一整套已有设备(至少一个,可重复;同设备重复列出
61	  只算一次,成员顺序不影响等价性,设备可属于多个分组);版本从生效时刻起
62	  生效直到下一版本接替,允许乱序补录历史版本。同组同一实际生效时刻、同
63	  成员集合重试成功且不新增,异成员集合报冲突;未知设备报错,配置整次成功
64	  或不提交。history 按生效时刻列出全部版本(只读)。daily 的 --from(含)
65	  与 --to(不含)必填且起点必须更早,按 UTC 自然日切分、按当时生效成员
66	  计算,首个版本生效前记为未知;每个时段只有全部生效成员均处于非下降读数
67	  区间才是有效覆盖并计入成员消耗之和,任一成员下降为异常,否则任一成员
68	  未知为未知;异常与未知时段不计任何成员消耗,覆盖秒数按分组实际时间计;
69	  各设备片段仍以原读数区间起点累计比例向下取整,日界线、查询边界与成员
70	  切换均不重置分摊起点,拆开查询相加一致。每天显示生效成员及其时段、估算
71	  消耗与有效/异常/未知秒数(三者之和等于当天查询时长);有异常或未知标为
72	  不完整,无有效覆盖显示无法计算。配置不改读数、规则和告警,导入不改配置。
73	
74	告警规则(rule / evaluate / alerts / ack):
75	  规则标识非空唯一,绑定的设备必须已有存储读数(去首尾空白、区分大小写);
76	  阈值非负、最多三位小数 kWh;创建后设备与阈值固定。相同标识等价参数重试
77	  成功且不重复创建,异参重试报冲突。
78	  evaluate 的 --from/--to 为 YYYY-MM-DD 的 UTC 日期,起日含、止日不含,
79	  起日必须更早。评估口径与 daily 相同:仅全天有效覆盖的日期可判定,消耗
80	  严格大于阈值才超限(等于为正常);有未知或下降覆盖的日期不可判定,不触发
81	  也不恢复。每个规则每个日期独立跟踪:首次超限创建带唯一标识的未确认告警,
82	  重复超限保留原标识;完整评估正常才记录恢复;恢复后再超限创建新的未确认
83	  告警,旧记录保留,原确认不转移。批量日期评估要么全部提交要么不提交。
84	  ack 按告警标识确认,已恢复告警也可确认;重复确认成功且不重复记事,确认
85	  不改变超限或恢复状态。alerts 按规则和日期展示消耗或不可判定原因、各次
86	  告警的标识、检测状态、确认状态及触发/恢复/确认的处理顺序;省略日期范围
87	  时展示有告警记录的全部日期。导入不自动评估,补导后需显式重评。
88	
89	CSV 格式:
90	  表头: ${CSV_HEADER}
91	  device   设备标识(区分大小写,首尾空白忽略,去空白后不能为空)
92	  time     秒精度 ISO8601,带 Z 或数字时区偏移;必须是真实日期
93	  reading  累计电表读数(kWh,非负,最多三位小数;可超出 Number 安全整数
94	           范围,任意大的十进制值都精确保存,如 9007199254740.991)
95	  支持标准双引号字段与 "" 转义;同一设备同一时刻(按实际时刻判定)
96	  重复且数值相同记为重复跳过,数值不同视为冲突并拒绝整批。
97	
98	数值精度:
99	  读数与阈值以毫千瓦时 BigInt 运算,解析、求差、分摊、汇总、比较、保存
100	  和显示全程精确,输出固定三位小数,不使用科学计数法。
101	  兼容旧版 readings.json / alerts.json 中以 JSON 数值保存的安全整数
102	  读数与阈值,无需手工转换;新版以十进制字符串保存。数值型毫千瓦时若
103	  已超出安全整数范围(精度已丢失)按损坏数据拒绝,不猜测原值。
104	
105	数据位置:
106	  $METERWATCH_DATA_DIR/readings.json(默认 ~/.meterwatch/readings.json)
107	  $METERWATCH_DATA_DIR/alerts.json(告警规则与历史,与读数文件相互独立)
108	  $METERWATCH_DATA_DIR/groups.json(分组配置,与读数、告警文件相互独立)
109	
110	退出码: 0 成功;1 数据或读写错误;2 参数错误`;
111	
112	function usageError(message: string): number {
113	  console.error(`${name}: ${message}`);
114	  console.error(`用法见 'node app.ts --help'`);
115	  return 2;
116	}
117	
118	interface ParsedOptions {
119	  devices: string[];
120	  from?: number;
121	  to?: number;
122	}
123	
124	/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
125	function parseOptions(rest: string[]): ParsedOptions | string {
126	  const devices: string[] = [];
127	  let from: number | undefined;
128	  let to: number | undefined;
129	  for (let i = 0; i < rest.length; i++) {
130	    let opt = rest[i];
131	    let value: string | undefined;
132	    const eq = opt.indexOf('=');
133	    if (opt.startsWith('--') && eq !== -1) {
134	      value = opt.slice(eq + 1);
135	      opt = opt.slice(0, eq);
136	    } else if (opt.startsWith('--')) {
137	      value = rest[i + 1];
138	      if (value === undefined) return `选项 '${opt}' 缺少值`;
139	      i++;
140	    } else {
141	      return `无法识别的参数 '${opt}'`;
142	    }
143	    if (opt === '--device') {
144	      if (value.trim() === '') return "'--device' 的值不能为空";
145	      devices.push(value);
146	    } else if (opt === '--from' || opt === '--to') {
147	      const ts = parseIso8601(value.trim());
148	      if (ts === null) {
149	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
150	      }
151	      if (opt === '--from') from = ts;
152	      else to = ts;
153	    } else {
154	      return `无法识别的选项 '${opt}'`;
155	    }
156	  }
157	  return { devices, from, to };
158	}
159	
160	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
161	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
162	  const out = new Map<string, string[]>();
163	  for (let i = 0; i < rest.length; i++) {
164	    let opt = rest[i];
165	    let value: string | undefined;
166	    const eq = opt.indexOf('=');
167	    if (opt.startsWith('--') && eq !== -1) {
168	      value = opt.slice(eq + 1);
169	      opt = opt.slice(0, eq);
170	    } else if (opt.startsWith('--')) {
171	      value = rest[i + 1];
172	      if (value === undefined) return `选项 '${opt}' 缺少值`;
173	      i++;
174	    } else {
175	      return `无法识别的参数 '${opt}'`;
176	    }
177	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
178	    const list = out.get(opt);
179	    if (list) list.push(value);
180	    else out.set(opt, [value]);
181	  }
182	  return out;
183	}
184	
185	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
186	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
187	  const list = flags.get(name);
188	  if (!list || list.length !== 1) return null;
189	  return list[0];
190	}
191	
192	/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
193	function dateFlag(value: string, label: string): number | string {
194	  const ts = parseUtcDate(value.trim());
195	  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
196	  return ts;
197	}
198	
199	function cmdRule(rest: string[]): number {
200	  const [sub, ...subrest] = rest;
201	  if (sub === 'list') {
202	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
203	    return cmdRuleList();
204	  }
205	  if (sub === 'create') {
206	    const flags = parseFlags(subrest, ['--id', '--device', '--threshold']);
207	    if (typeof flags === 'string') return usageError(flags);
208	    const idRaw = oneFlag(flags, '--id');
209	    const deviceRaw = oneFlag(flags, '--device');
210	    const thresholdRaw = oneFlag(flags, '--threshold');
211	    if (idRaw === null || deviceRaw === null || thresholdRaw === null) {
212	      return usageError("'rule create' 需要 --id、--device、--threshold 各恰好一个");
213	    }
214	    const id = idRaw.trim();
215	    if (id === '') return usageError('规则标识不能为空');
216	    const device = deviceRaw.trim();
217	    if (device === '') return usageError("'--device' 的值不能为空");
218	    const thresholdMilli = parseKwh(thresholdRaw.trim());
219	    if (thresholdMilli === null) {
220	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
221	    }
222	    return cmdRuleCreate({ id, device, thresholdMilli });
223	  }
224	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
225	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
226	}
227	
228	function cmdEvaluateEntry(rest: string[]): number {
229	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
230	  if (typeof flags === 'string') return usageError(flags);
231	  const ruleRaw = oneFlag(flags, '--rule');
232	  const fromRaw = oneFlag(flags, '--from');
233	  const toRaw = oneFlag(flags, '--to');
234	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
235	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
236	  }
237	  const ruleId = ruleRaw.trim();
238	  if (ruleId === '') return usageError('规则标识不能为空');
239	  const from = dateFlag(fromRaw, '起始日期');
240	  if (typeof from === 'string') return usageError(from);
241	  const to = dateFlag(toRaw, '结束日期');
242	  if (typeof to === 'string') return usageError(to);
243	  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
244	  return cmdEvaluate({ ruleId, from, to });
245	}
246	
247	function cmdAlertsEntry(rest: string[]): number {
248	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
249	  if (typeof flags === 'string') return usageError(flags);
250	  const ruleRaw = oneFlag(flags, '--rule');
251	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
252	  const ruleId = ruleRaw.trim();
253	  if (ruleId === '') return usageError('规则标识不能为空');
254	  const fromList = flags.get('--from');
255	  const toList = flags.get('--to');
256	  if ((fromList !== undefined) !== (toList !== undefined)) {
257	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
258	  }
259	  let from: number | undefined;
260	  let to: number | undefined;
261	  if (fromList !== undefined) {
262	    const fromRaw = oneFlag(flags, '--from');
263	    const toRaw = oneFlag(flags, '--to');
264	    if (fromRaw === null || toRaw === null) {
265	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
266	    }
267	    const fromParsed = dateFlag(fromRaw, '起始日期');
268	    if (typeof fromParsed === 'string') return usageError(fromParsed);
269	    const toParsed = dateFlag(toRaw, '结束日期');
270	    if (typeof toParsed === 'string') return usageError(toParsed);
271	    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
272	    from = fromParsed;
273	    to = toParsed;
274	  }
275	  return cmdAlerts({ ruleId, from, to });
276	}
277	
278	function cmdGroup(rest: string[]): number {
279	  const [sub, ...subrest] = rest;
280	  if (sub === 'configure') {
281	    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
282	    if (typeof flags === 'string') return usageError(flags);
283	    const idRaw = oneFlag(flags, '--id');
284	    const atRaw = oneFlag(flags, '--at');
285	    const deviceList = flags.get('--device') ?? [];
286	    if (idRaw === null || atRaw === null) {
287	      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
288	    }
289	    if (deviceList.length === 0) {
290	      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
291	    }
292	    const id = idRaw.trim();
293	    if (id === '') return usageError('分组标识不能为空');
294	    const at = parseIso8601(atRaw.trim());
295	    if (at === null) {
296	      return usageError(
297	        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
298	      );
299	    }
300	    const members: string[] = [];
301	    for (const d of deviceList) {
302	      const m = d.trim();
303	      if (m === '') return usageError("'--device' 的值不能为空");
304	      members.push(m);
305	    }
306	    return cmdGroupConfigure({ id, at, members });
307	  }
308	  if (sub === 'history') {
309	    const flags = parseFlags(subrest, ['--id']);
310	    if (typeof flags === 'string') return usageError(flags);
311	    const idRaw = oneFlag(flags, '--id');
312	    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
313	    const id = idRaw.trim();
314	    if (id === '') return usageError('分组标识不能为空');
315	    return cmdGroupHistory({ id });
316	  }
317	  if (sub === 'daily') {
318	    const flags = parseFlags(subrest, ['--id', '--from', '--to']);
319	    if (typeof flags === 'string') return usageError(flags);
320	    const idRaw = oneFlag(flags, '--id');
321	    const fromRaw = oneFlag(flags, '--from');
322	    const toRaw = oneFlag(flags, '--to');
323	    if (idRaw === null || fromRaw === null || toRaw === null) {
324	      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
325	    }
326	    const id = idRaw.trim();
327	    if (id === '') return usageError('分组标识不能为空');
328	    const from = parseIso8601(fromRaw.trim());
329	    if (from === null) {
330	      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
331	    }
332	    const to = parseIso8601(toRaw.trim());
333	    if (to === null) {
334	      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
335	    }
336	    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
337	    return cmdGroupDaily({ id, from, to });
338	  }
339	  if (sub === undefined) return usageError("'group' 需要子命令 configure、history 或 daily");
340	  return usageError(`无法识别的 group 子命令 '${sub}'`);
341	}
342	
343	function main(args: string[]): number {
344	  if (args.length === 0) {
345	    console.log(help);
346	    return 0;
347	  }
348	  const [cmd, ...rest] = args;
349	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
350	    console.log(help);
351	    return 0;
352	  }
353	
354	  if (cmd === 'import') {
355	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
356	    return cmdImport(rest[0]);
357	  }
358	
359	  if (cmd === 'readings') {
360	    const parsed = parseOptions(rest);
361	    if (typeof parsed === 'string') return usageError(parsed);
362	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
363	      return usageError('查询起点必须早于终点(--from < --to)');
364	    }
365	    return cmdReadings(parsed);
366	  }
367	
368	  if (cmd === 'daily') {
369	    const parsed = parseOptions(rest);
370	    if (typeof parsed === 'string') return usageError(parsed);
371	    if (parsed.from === undefined || parsed.to === undefined) {
372	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
373	    }
374	    if (parsed.from >= parsed.to) {
375	      return usageError('查询起点必须早于终点(--from < --to)');
376	    }
