import { cmdImport, cmdReadings, CSV_HEADER } from './src/commands.ts';
import { cmdDaily } from './src/report.ts';
import { cmdAck, cmdAlerts, cmdEvaluate, cmdRuleCreate, cmdRuleList } from './src/alerts.ts';
import { cmdGroupConfigure, cmdGroupDaily, cmdGroupHistory } from './src/groups.ts';
import { parseIso8601, parseUtcDate } from './src/time.ts';
import { parseKwh } from './src/value.ts';

const name = 'meterwatch';

const help = `${name}

建筑能耗监测:本地累计电表读数导入与消耗核查。

Usage:
  node app.ts                       显示本帮助
  node app.ts --help | -h           显示本帮助
  node app.ts import <file.csv>     导入 CSV 读数(整批成功或整批拒绝)
  node app.ts readings [筛选...]    查询读数、区间与消耗
  node app.ts daily --from <iso> --to <iso> [--device <id>...]
                                    按 UTC 自然日核查能耗的只读日报
  node app.ts rule create --id <id> --device <设备> --threshold <kWh>
                                    创建每日能耗阈值告警规则
  node app.ts rule list             查看全部告警规则
  node app.ts evaluate --rule <id> --from <日期> --to <日期>
                                    评估规则在连续完整 UTC 日期上的超限情况
  node app.ts alerts --rule <id> [--from <日期> --to <日期>]
                                    查询规则的告警历史(只读)
  node app.ts ack <告警标识>         确认告警
  node app.ts group configure --id <id> --at <iso> --device <id>...
                                    配置分组成员版本(首次配置即建立分组)
  node app.ts group history --id <id>
                                    查看分组成员版本历史(只读)
  node app.ts group daily --id <id> --from <iso> --to <iso>
                                    按当时生效成员的分组能耗日报(只读)

筛选(readings):
  --device <id>     只显示指定设备(可重复使用,区分大小写)
  --from <iso8601>  起始时刻(含),如 2026-01-01T00:00:00Z
  --to <iso8601>    结束时刻(不含)
  省略边界表示不限;时间必须为秒精度 ISO8601 且带 Z 或数字时区偏移
  (如 +08:00);起点不早于终点时拒绝查询。

日报(daily):
  --from <iso8601>  起始时刻(含),必填
  --to <iso8601>    结束时刻(不含),必填,必须晚于起点
  --device <id>     只统计指定设备(可重复使用);省略时统计库内全部设备
  日期按 UTC 零点划分,首尾日期只统计与查询范围重叠的部分。
  估算口径:由每个设备完整时序的相邻读数构成区间,区间两端读数即使在
  查询范围外也参与;非下降区间把累计值之差按持续时间均匀分摊,以千分之一
  kWh 为单位,从区间起点累计到切点(查询边界与日界线)向下取整,片段消耗
  为两端累计量之差,故完整区间的分摊总量等于原差值,同一区间拆开查询再
  相加结果一致。下降区间不分摊,记为异常覆盖;首条读数之前、末条之后及
  孤立读数时段为未知,不外推。每天输出估算消耗与有效/异常/未知覆盖秒数
  (三者之和等于该天查询时长);存在未知或异常覆盖时日报标记为不完整。
  日报只读,不写入数据。

分组(group configure / history / daily):
  分组以首次 configure 建立,标识非空唯一(去首尾空白、区分大小写)。
  configure 的 --at 为版本生效时刻(含,秒精度 ISO8601 带 Z 或数字时区
  偏移),--device 给出一整套已有设备(至少一个,可重复;同设备重复列出
  只算一次,成员顺序不影响等价性,设备可属于多个分组);版本从生效时刻起
  生效直到下一版本接替,允许乱序补录历史版本。同组同一实际生效时刻、同
  成员集合重试成功且不新增,异成员集合报冲突;未知设备报错,配置整次成功
  或不提交。history 按生效时刻列出全部版本(只读)。daily 的 --from(含)
  与 --to(不含)必填且起点必须更早,按 UTC 自然日切分、按当时生效成员
  计算,首个版本生效前记为未知;每个时段只有全部生效成员均处于非下降读数
  区间才是有效覆盖并计入成员消耗之和,任一成员下降为异常,否则任一成员
  未知为未知;异常与未知时段不计任何成员消耗,覆盖秒数按分组实际时间计;
  各设备片段仍以原读数区间起点累计比例向下取整,日界线、查询边界与成员
  切换均不重置分摊起点,拆开查询相加一致。每天显示生效成员及其时段、估算
  消耗与有效/异常/未知秒数(三者之和等于当天查询时长);有异常或未知标为
  不完整,无有效覆盖显示无法计算。配置不改读数、规则和告警,导入不改配置。

告警规则(rule / evaluate / alerts / ack):
  规则标识非空唯一,绑定的设备必须已有存储读数(去首尾空白、区分大小写);
  阈值非负、最多三位小数 kWh;创建后设备与阈值固定。相同标识等价参数重试
  成功且不重复创建,异参重试报冲突。
  evaluate 的 --from/--to 为 YYYY-MM-DD 的 UTC 日期,起日含、止日不含,
  起日必须更早。评估口径与 daily 相同:仅全天有效覆盖的日期可判定,消耗
  严格大于阈值才超限(等于为正常);有未知或下降覆盖的日期不可判定,不触发
  也不恢复。每个规则每个日期独立跟踪:首次超限创建带唯一标识的未确认告警,
  重复超限保留原标识;完整评估正常才记录恢复;恢复后再超限创建新的未确认
  告警,旧记录保留,原确认不转移。批量日期评估要么全部提交要么不提交。
  ack 按告警标识确认,已恢复告警也可确认;重复确认成功且不重复记事,确认
  不改变超限或恢复状态。alerts 按规则和日期展示消耗或不可判定原因、各次
  告警的标识、检测状态、确认状态及触发/恢复/确认的处理顺序;省略日期范围
  时展示有告警记录的全部日期。导入不自动评估,补导后需显式重评。

CSV 格式:
  表头: ${CSV_HEADER}
  device   设备标识(区分大小写,首尾空白忽略,去空白后不能为空)
  time     秒精度 ISO8601,带 Z 或数字时区偏移;必须是真实日期
  reading  累计电表读数(kWh,非负,最多三位小数;可超出 Number 安全整数
           范围,任意大的十进制值都精确保存,如 9007199254740.991)
  支持标准双引号字段与 "" 转义;同一设备同一时刻(按实际时刻判定)
  重复且数值相同记为重复跳过,数值不同视为冲突并拒绝整批。

数值精度:
  读数与阈值以毫千瓦时 BigInt 运算,解析、求差、分摊、汇总、比较、保存
  和显示全程精确,输出固定三位小数,不使用科学计数法。
  兼容旧版 readings.json / alerts.json 中以 JSON 数值保存的安全整数
  读数与阈值,无需手工转换;新版以十进制字符串保存。数值型毫千瓦时若
  已超出安全整数范围(精度已丢失)按损坏数据拒绝,不猜测原值。

数据位置:
  $METERWATCH_DATA_DIR/readings.json(默认 ~/.meterwatch/readings.json)
  $METERWATCH_DATA_DIR/alerts.json(告警规则与历史,与读数文件相互独立)
  $METERWATCH_DATA_DIR/groups.json(分组配置,与读数、告警文件相互独立)

退出码: 0 成功;1 数据或读写错误;2 参数错误`;

function usageError(message: string): number {
  console.error(`${name}: ${message}`);
  console.error(`用法见 'node app.ts --help'`);
  return 2;
}

interface ParsedOptions {
  devices: string[];
  from?: number;
  to?: number;
}

/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
function parseOptions(rest: string[]): ParsedOptions | string {
  const devices: string[] = [];
  let from: number | undefined;
  let to: number | undefined;
  for (let i = 0; i < rest.length; i++) {
    let opt = rest[i];
    let value: string | undefined;
    const eq = opt.indexOf('=');
    if (opt.startsWith('--') && eq !== -1) {
      value = opt.slice(eq + 1);
      opt = opt.slice(0, eq);
    } else if (opt.startsWith('--')) {
      value = rest[i + 1];
      if (value === undefined) return `选项 '${opt}' 缺少值`;
      i++;
    } else {
      return `无法识别的参数 '${opt}'`;
    }
    if (opt === '--device') {
      if (value.trim() === '') return "'--device' 的值不能为空";
      devices.push(value);
    } else if (opt === '--from' || opt === '--to') {
      const ts = parseIso8601(value.trim());
      if (ts === null) {
        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
      }
      if (opt === '--from') from = ts;
      else to = ts;
    } else {
      return `无法识别的选项 '${opt}'`;
    }
  }
  return { devices, from, to };
}

/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
  const out = new Map<string, string[]>();
  for (let i = 0; i < rest.length; i++) {
    let opt = rest[i];
    let value: string | undefined;
    const eq = opt.indexOf('=');
    if (opt.startsWith('--') && eq !== -1) {
      value = opt.slice(eq + 1);
      opt = opt.slice(0, eq);
    } else if (opt.startsWith('--')) {
      value = rest[i + 1];
      if (value === undefined) return `选项 '${opt}' 缺少值`;
      i++;
    } else {
      return `无法识别的参数 '${opt}'`;
    }
    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
    const list = out.get(opt);
    if (list) list.push(value);
    else out.set(opt, [value]);
  }
  return out;
}

/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
function oneFlag(flags: Map<string, string[]>, name: string): string | null {
  const list = flags.get(name);
  if (!list || list.length !== 1) return null;
  return list[0];
}

/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
function dateFlag(value: string, label: string): number | string {
  const ts = parseUtcDate(value.trim());
  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
  return ts;
}

function cmdRule(rest: string[]): number {
  const [sub, ...subrest] = rest;
  if (sub === 'list') {
    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
    return cmdRuleList();
  }
  if (sub === 'create') {
    const flags = parseFlags(subrest, ['--id', '--device', '--threshold']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    const deviceRaw = oneFlag(flags, '--device');
    const thresholdRaw = oneFlag(flags, '--threshold');
    if (idRaw === null || deviceRaw === null || thresholdRaw === null) {
      return usageError("'rule create' 需要 --id、--device、--threshold 各恰好一个");
    }
    const id = idRaw.trim();
    if (id === '') return usageError('规则标识不能为空');
    const device = deviceRaw.trim();
    if (device === '') return usageError("'--device' 的值不能为空");
    const thresholdMilli = parseKwh(thresholdRaw.trim());
    if (thresholdMilli === null) {
      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
    }
    return cmdRuleCreate({ id, device, thresholdMilli });
  }
  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
  return usageError(`无法识别的 rule 子命令 '${sub}'`);
}

function cmdEvaluateEntry(rest: string[]): number {
  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
  if (typeof flags === 'string') return usageError(flags);
  const ruleRaw = oneFlag(flags, '--rule');
  const fromRaw = oneFlag(flags, '--from');
  const toRaw = oneFlag(flags, '--to');
  if (ruleRaw === null || fromRaw === null || toRaw === null) {
    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
  }
  const ruleId = ruleRaw.trim();
  if (ruleId === '') return usageError('规则标识不能为空');
  const from = dateFlag(fromRaw, '起始日期');
  if (typeof from === 'string') return usageError(from);
  const to = dateFlag(toRaw, '结束日期');
  if (typeof to === 'string') return usageError(to);
  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
  return cmdEvaluate({ ruleId, from, to });
}

function cmdAlertsEntry(rest: string[]): number {
  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
  if (typeof flags === 'string') return usageError(flags);
  const ruleRaw = oneFlag(flags, '--rule');
  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
  const ruleId = ruleRaw.trim();
  if (ruleId === '') return usageError('规则标识不能为空');
  const fromList = flags.get('--from');
  const toList = flags.get('--to');
  if ((fromList !== undefined) !== (toList !== undefined)) {
    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
  }
  let from: number | undefined;
  let to: number | undefined;
  if (fromList !== undefined) {
    const fromRaw = oneFlag(flags, '--from');
    const toRaw = oneFlag(flags, '--to');
    if (fromRaw === null || toRaw === null) {
      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
    }
    const fromParsed = dateFlag(fromRaw, '起始日期');
    if (typeof fromParsed === 'string') return usageError(fromParsed);
    const toParsed = dateFlag(toRaw, '结束日期');
    if (typeof toParsed === 'string') return usageError(toParsed);
    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
    from = fromParsed;
    to = toParsed;
  }
  return cmdAlerts({ ruleId, from, to });
}

function cmdGroup(rest: string[]): number {
  const [sub, ...subrest] = rest;
  if (sub === 'configure') {
    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    const atRaw = oneFlag(flags, '--at');
    const deviceList = flags.get('--device') ?? [];
    if (idRaw === null || atRaw === null) {
      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
    }
    if (deviceList.length === 0) {
      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
    }
    const id = idRaw.trim();
    if (id === '') return usageError('分组标识不能为空');
    const at = parseIso8601(atRaw.trim());
    if (at === null) {
      return usageError(
        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
      );
    }
    const members: string[] = [];
    for (const d of deviceList) {
      const m = d.trim();
      if (m === '') return usageError("'--device' 的值不能为空");
      members.push(m);
    }
    return cmdGroupConfigure({ id, at, members });
  }
  if (sub === 'history') {
    const flags = parseFlags(subrest, ['--id']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
    const id = idRaw.trim();
    if (id === '') return usageError('分组标识不能为空');
    return cmdGroupHistory({ id });
  }
  if (sub === 'daily') {
    const flags = parseFlags(subrest, ['--id', '--from', '--to']);
    if (typeof flags === 'string') return usageError(flags);
    const idRaw = oneFlag(flags, '--id');
    const fromRaw = oneFlag(flags, '--from');
    const toRaw = oneFlag(flags, '--to');
    if (idRaw === null || fromRaw === null || toRaw === null) {
      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
    }
    const id = idRaw.trim();
    if (id === '') return usageError('分组标识不能为空');
    const from = parseIso8601(fromRaw.trim());
    if (from === null) {
      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
    }
    const to = parseIso8601(toRaw.trim());
    if (to === null) {
      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
    }
    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
    return cmdGroupDaily({ id, from, to });
  }
  if (sub === undefined) return usageError("'group' 需要子命令 configure、history 或 daily");
  return usageError(`无法识别的 group 子命令 '${sub}'`);
}

function main(args: string[]): number {
  if (args.length === 0) {
    console.log(help);
    return 0;
  }
  const [cmd, ...rest] = args;
  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
    console.log(help);
    return 0;
  }

  if (cmd === 'import') {
    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
    return cmdImport(rest[0]);
  }

  if (cmd === 'readings') {
    const parsed = parseOptions(rest);
    if (typeof parsed === 'string') return usageError(parsed);
    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
      return usageError('查询起点必须早于终点(--from < --to)');
    }
    return cmdReadings(parsed);
  }

  if (cmd === 'daily') {
    const parsed = parseOptions(rest);
    if (typeof parsed === 'string') return usageError(parsed);
    if (parsed.from === undefined || parsed.to === undefined) {
      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
    }
    if (parsed.from >= parsed.to) {
      return usageError('查询起点必须早于终点(--from < --to)');
    }
    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to });
  }

  if (cmd === 'rule') return cmdRule(rest);
  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
  if (cmd === 'alerts') return cmdAlertsEntry(rest);
  if (cmd === 'group') return cmdGroup(rest);

  if (cmd === 'ack') {
    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
    const alertId = rest[0].trim();
    if (alertId === '') return usageError('告警标识不能为空');
    return cmdAck(alertId);
  }

  return usageError(`无法识别的参数 '${cmd}'`);
}

process.exitCode = main(process.argv.slice(2));

content.content:
1	// group 子命令:分组成员版本配置、成员历史查询与分组能耗日报。
2	//
3	// - 分组以首次配置建立,标识非空唯一(去首尾空白、区分大小写);每次配置指定
4	//   生效时刻(含)与一整套已有设备,从该时刻起生效直到下一版本接替;允许乱序
5	//   补录历史版本。成员不能为空,同设备重复列出只算一次,成员顺序不影响等价性,
6	//   设备可属于多个分组。同组同一实际生效时刻、同成员集合重试成功且不新增,
7	//   异成员集合报冲突。
8	// - 配置整次成功或不提交:未知设备、冲突、损坏或不可读存储及写入失败都明确
9	//   报错并保留操作前状态。配置不改读数、规则和告警,导入也不改配置。
10	// - 日报按 UTC 自然日切分(起点含、终点不含,首尾只统计重叠部分),按当时生效
11	//   成员计算,不把最新成员套用到历史;首个版本生效前记为未知。各设备使用完整
12	//   已存时序,区间两端读数即使在查询范围外也参与;成员切换不需要恰好有读数,
13	//   首条读数之前、末条之后及孤立读数时段为未知,不外推。
14	// - 每个时段只有全部生效成员均处于非下降读数区间时才是有效覆盖,并计入成员
15	//   消耗之和;任一成员下降则为异常覆盖,否则任一成员未知则为未知覆盖。异常与
16	//   未知时段不计任何成员消耗,不以缺失设备为零补齐。覆盖秒数按分组实际时间
17	//   计算,不累加成员秒数。各设备片段仍以原读数区间起点累计比例向下取整,
18	//   两端累计量之差为消耗;日界线、查询边界与成员切换均不重置分摊起点,
19	//   拆开查询相加结果一致。全程 BigInt 精确计算,kWh 固定三位小数。
20	// - 日报与历史只读;读取读数时拒绝同设备同一实际时刻的多条存储记录。
21	
22	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
23	import { dirname } from 'node:path';
24	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
25	import { DAY_SECONDS } from './report.ts';
26	import { formatIsoUtc } from './time.ts';
27	import { formatKwh } from './value.ts';
28	
29	export interface GroupVersion {
30	  /** 生效时刻(含),epoch 秒。 */
31	  at: number;
32	  /** 成员设备标识,已去重并按字典序排序(规范形,成员顺序不影响等价性)。 */
33	  members: string[];
34	}
35	
36	export interface Group {
37	  /** 分组标识(非空、唯一,已去首尾空白,区分大小写)。 */
38	  id: string;
39	  /** 成员版本,按生效时刻升序。 */
40	  versions: GroupVersion[];
41	}
42	
43	function err(message: string): void {
44	  console.error(`meterwatch: ${message}`);
45	}
46	
47	/** 读取分组存储;文件不存在返回空数组,存在但无法读取或内容损坏抛出 StoreError。 */
48	function loadGroups(path: string): Group[] {
49	  let text: string;
50	  try {
51	    text = readFileSync(path, 'utf8');
52	  } catch (e) {
53	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return [];
54	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
55	  }
56	  let data: unknown;
57	  try {
58	    data = JSON.parse(text);
59	  } catch {
60	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
61	  }
62	  const bad = (what: string): StoreError =>
63	    new StoreError(`storage file ${path} is corrupted (${what})`);
64	  const o = data as Record<string, unknown>;
65	  if (o === null || typeof o !== 'object') throw bad('not an object');
66	  if (!Array.isArray(o.groups)) throw bad('missing groups array');
67	
68	  const ids = new Set<string>();
69	  const groups: Group[] = [];
70	  for (const g of o.groups as Array<Record<string, unknown>>) {
71	    const ok =
72	      g !== null &&
73	      typeof g === 'object' &&
74	      typeof g.id === 'string' &&
75	      g.id.length > 0 &&
76	      Array.isArray(g.versions) &&
77	      g.versions.length > 0;
78	    if (!ok) throw bad('invalid group entry');
79	    if (ids.has(g.id as string)) throw bad(`duplicate group id '${g.id}'`);
80	    ids.add(g.id as string);
81	
82	    const versions: GroupVersion[] = [];
83	    const seenAts = new Set<number>();
84	    for (const v of g.versions as Array<Record<string, unknown>>) {
85	      const vok =
86	        v !== null &&
87	        typeof v === 'object' &&
88	        Number.isSafeInteger(v.at) &&
89	        Array.isArray(v.members) &&
90	        v.members.length > 0 &&
91	        (v.members as unknown[]).every((m) => typeof m === 'string' && (m as string).length > 0);
92	      if (!vok) throw bad(`invalid version entry in group '${g.id}'`);
93	      const at = v.at as number;
94	      if (seenAts.has(at)) throw bad(`duplicate version time in group '${g.id}'`);
95	      seenAts.add(at);
96	      const members = [...(v.members as string[])].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
97	      for (let i = 1; i < members.length; i++) {
98	        if (members[i] === members[i - 1]) {
99	          throw bad(`duplicate member '${members[i]}' in group '${g.id}'`);
100	        }
101	      }
102	      versions.push({ at, members });
103	    }
104	    versions.sort((a, b) => a.at - b.at);
105	    groups.push({ id: g.id as string, versions });
106	  }
107	  return groups;
108	}
109	
110	/** 原子写入分组存储;失败抛错,原有数据保持不变。 */
111	function saveGroups(path: string, groups: Group[]): void {
112	  mkdirSync(dirname(path), { recursive: true });
113	  const tmp = `${path}.tmp-${process.pid}`;
114	  const body = JSON.stringify({ version: 1, groups }, null, 2) + '\n';
115	  try {
116	    writeFileSync(tmp, body, 'utf8');
117	    renameSync(tmp, path);
118	  } catch (e) {
119	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
120	  }
121	}
122	
123	/**
124	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
125	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
126	 */
127	function deviceSeries(all: Reading[], device: string): Reading[] {
128	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
129	  for (let i = 1; i < series.length; i++) {
130	    if (series[i].ts === series[i - 1].ts) {
131	      throw new StoreError(
132	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
133	      );
134	    }
135	  }
136	  return series;
137	}
138	
139	/** 在按时刻升序的时序中找最后一条 ts <= s 的下标,无则 -1。 */
140	function floorIndex(series: Reading[], s: number): number {
141	  let lo = 0;
142	  let hi = series.length - 1;
143	  let ans = -1;
144	  while (lo <= hi) {
145	    const mid = (lo + hi) >> 1;
146	    if (series[mid].ts <= s) {
147	      ans = mid;
148	      lo = mid + 1;
149	    } else {
150	      hi = mid - 1;
151	    }
152	  }
153	  return ans;
154	}
155	
156	type SliceKind = 'valid' | 'anomaly' | 'unknown';
157	
158	/**
159	 * 单设备在片段 [s, e) 上的状态与消耗。片段完全落在同一读数区间内
160	 * (调用方保证切点包含区间内全部读数时刻)。非下降区间以区间起点累计
161	 * 比例向下取整,消耗为两端累计量之差;下降区间为异常;首条读数之前、
162	 * 末条之后及孤立读数时段为未知,不外推。
163	 */
164	function deviceSlice(
165	  series: Reading[],
166	  s: number,
167	  e: number,
168	): { kind: SliceKind; consumption: bigint } {
169	  const i = floorIndex(series, s);
170	  if (i < 0 || i + 1 >= series.length) return { kind: 'unknown', consumption: 0n };
171	  const a = series[i];
172	  const b = series[i + 1];
173	  const diff = b.milli - a.milli;
174	  if (diff < 0n) return { kind: 'anomaly', consumption: 0n };
175	  const duration = BigInt(b.ts - a.ts);
176	  const cumulative = (t: number): bigint => (diff * BigInt(t - a.ts)) / duration;
177	  return { kind: 'valid', consumption: cumulative(e) - cumulative(s) };
178	}
179	
180	export interface GroupPeriod {
181	  /** 时段起点(含),epoch 秒。 */
182	  start: number;
183	  /** 时段终点(不含),epoch 秒。 */
184	  end: number;
185	  /** 该时段生效成员;null 表示首个版本生效前(未知)。 */
186	  members: string[] | null;
187	}
188	
189	export interface GroupSegmentStats {
190	  /** 有效(全部成员非下降)覆盖秒数,按分组实际时间计。 */
191	  valid: number;
192	  /** 异常(任一成员下降)覆盖秒数。 */
193	  anomaly: number;
194	  /** 未知(无生效版本或任一成员未知)覆盖秒数。 */
195	  unknown: number;
196	  /** 有效时段内全部生效成员的分摊消耗之和,毫千瓦时 BigInt。 */
197	  consumption: bigint;
198	  /** 段内按生效时刻切分的成员时段。 */
199	  periods: GroupPeriod[];
200	}
201	
202	/**
203	 * 计算分组在 [segStart, segEnd) 上的覆盖与消耗。
204	 * versions 按生效时刻升序;seriesByDevice 含全部版本成员的完整时序。
205	 */
206	export function computeGroupSegment(
207	  versions: GroupVersion[],
208	  seriesByDevice: Map<string, Reading[]>,
209	  segStart: number,
210	  segEnd: number,
211	): GroupSegmentStats {
212	  // 按版本生效时刻把段切成成员恒定的时段;首个版本生效前 members 为 null。
213	  const periods: GroupPeriod[] = [];
214	  let idx = -1;
215	  for (let i = 0; i < versions.length; i++) {
216	    if (versions[i].at <= segStart) idx = i;
217	    else break;
218	  }
219	  let cursor = segStart;
220	  while (cursor < segEnd) {
221	    const nextAt = idx + 1 < versions.length ? versions[idx + 1].at : Number.POSITIVE_INFINITY;
222	    const pEnd = Math.min(segEnd, nextAt);
223	    periods.push({ start: cursor, end: pEnd, members: idx >= 0 ? versions[idx].members : null });
224	    cursor = pEnd;
225	    idx++;
226	  }
227	
228	  let valid = 0;
229	  let anomaly = 0;
230	  let unknown = 0;
231	  let consumption = 0n;
232	  for (const p of periods) {
233	    if (p.members === null) {
234	      unknown += p.end - p.start;
235	      continue;
236	    }
237	    // 切点:时段边界与全部成员的读数时刻;相邻切点间每个成员的状态恒定。
238	    const bounds = new Set<number>([p.start, p.end]);
239	    for (const m of p.members) {
240	      for (const r of seriesByDevice.get(m) ?? []) {
241	        if (r.ts > p.start && r.ts < p.end) bounds.add(r.ts);
242	      }
243	    }
244	    const sorted = [...bounds].sort((a, b) => a - b);
245	    for (let k = 0; k + 1 < sorted.length; k++) {
246	      const s = sorted[k];
247	      const e = sorted[k + 1];
248	      let anyAnomaly = false;
249	      let anyUnknown = false;
250	      let slice = 0n;
251	      for (const m of p.members) {
252	        const res = deviceSlice(seriesByDevice.get(m) ?? [], s, e);
253	        if (res.kind === 'anomaly') anyAnomaly = true;
254	        else if (res.kind === 'unknown') anyUnknown = true;
255	        else slice += res.consumption;
256	      }
257	      if (anyAnomaly) {
258	        anomaly += e - s;
259	      } else if (anyUnknown) {
260	        unknown += e - s;
261	      } else {
262	        valid += e - s;
263	        consumption += slice;
264	      }
265	    }
266	  }
267	  return { valid, anomaly, unknown, consumption, periods };
268	}
269	
270	/**
271	 * 配置分组成员版本。首次配置即建立分组;同组同一实际生效时刻、同成员集合
272	 * 重试成功且不新增,异成员集合报冲突。整次成功或不提交。返回进程退出码。
273	 */
274	export function cmdGroupConfigure(opts: { id: string; at: number; members: string[] }): number {
275	  const path = groupFilePath();
276	  let groups: Group[];
277	  try {
278	    groups = loadGroups(path);
279	  } catch (e) {
280	    if (e instanceof StoreError) {
281	      err(e.message);
282	      return 1;
283	    }
284	    throw e;
285	  }
286	
287	  // 规范形:同设备重复列出只算一次,成员顺序不影响等价性。
288	  const members = [...new Set(opts.members)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
289	
290	  let known: Set<string>;
291	  try {
292	    known = new Set(loadStore(dataFilePath()).map((r) => r.device));
293	  } catch (e) {
294	    if (e instanceof StoreError) {
295	      err(e.message);
296	      return 1;
297	    }
298	    throw e;
299	  }
300	  for (const m of members) {
301	    if (!known.has(m)) {
302	      err(`unknown device '${m}': no stored readings; import readings before configuring a group`);
303	      return 1;
304	    }
305	  }
306	
307	  const existing = groups.find((g) => g.id === opts.id);
308	  if (existing) {
309	    const v = existing.versions.find((ver) => ver.at === opts.at);
310	    if (v) {
311	      const same =
312	        v.members.length === members.length && v.members.every((m, i) => m === members[i]);
313	      if (same) {
314	        console.log(
315	          `group '${opts.id}' already has an identical member version at ${formatIsoUtc(opts.at)}; unchanged`,
316	        );
317	        return 0;
318	      }
319	      err(
320	        `group '${opts.id}' already has a different member version at ${formatIsoUtc(opts.at)} ` +
321	          `(stored members=${v.members.join(',')}, got members=${members.join(',')}); conflict`,
322	      );
323	      return 1;
324	    }
325	    existing.versions.push({ at: opts.at, members });
326	    existing.versions.sort((a, b) => a.at - b.at);
327	  } else {
328	    groups.push({ id: opts.id, versions: [{ at: opts.at, members }] });
329	  }
330	
331	  try {
332	    saveGroups(path, groups);
333	  } catch (e) {
334	    if (e instanceof StoreError) {
335	      err(e.message);
336	      return 1;
337	    }
338	    throw e;
339	  }
340	  console.log(
341	    `group '${opts.id}' configured: members=${members.join(',')} effective ${formatIsoUtc(opts.at)}`,
342	  );
343	  return 0;
344	}
345	
346	/** 查看分组成员版本历史,按生效时刻排序。只读。返回进程退出码。 */
347	export function cmdGroupHistory(opts: { id: string }): number {
348	  let groups: Group[];
349	  try {
350	    groups = loadGroups(groupFilePath());
351	  } catch (e) {
352	    if (e instanceof StoreError) {
353	      err(e.message);
354	      return 1;
355	    }
356	    throw e;
357	  }
358	  const group = groups.find((g) => g.id === opts.id);
359	  if (!group) {
360	    err(`unknown group '${opts.id}'`);
361	    return 1;
362	  }
363	  console.log(`group: ${group.id}`);
364	  for (const v of group.versions) {
365	    console.log(`  ${formatIsoUtc(v.at)}  members=${v.members.join(',')}`);
366	  }
367	  return 0;
368	}
369	
370	/**
371	 * 分组能耗日报:按 UTC 自然日切分,按当时生效成员计算。只读,不写入数据。
372	 * 返回进程退出码。
373	 */
374	export function cmdGroupDaily(opts: { id: string; from: number; to: number }): number {
375	  let groups: Group[];
376	  try {
377	    groups = loadGroups(groupFilePath());
378	  } catch (e) {
379	    if (e instanceof StoreError) {
380	      err(e.message);
381	      return 1;
382	    }
383	    throw e;
384	  }
385	  const group = groups.find((g) => g.id === opts.id);
386	  if (!group) {
387	    err(`unknown group '${opts.id}'`);
388	    return 1;
389	  }
390	
391	  let seriesByDevice: Map<string, Reading[]>;
392	  try {
393	    const all = loadStore(dataFilePath());
394	    seriesByDevice = new Map();
395	    for (const v of group.versions) {
396	      for (const m of v.members) {
397	        if (!seriesByDevice.has(m)) seriesByDevice.set(m, deviceSeries(all, m));
398	      }
399	    }
400	  } catch (e) {
401	    if (e instanceof StoreError) {
402	      err(e.message);
403	      return 1;
404	    }
405	    throw e;
406	  }
407	
408	  console.log(`group: ${group.id}`);
409	  let total = 0n;
410	  let computedDays = 0;
411	  let days = 0;
412	  let incomplete = false;
413	  for (
414	    let dayStart = Math.floor(opts.from / DAY_SECONDS) * DAY_SECONDS;
415	    dayStart < opts.to;
416	    dayStart += DAY_SECONDS
417	  ) {
418	    const segStart = Math.max(dayStart, opts.from);
419	    const segEnd = Math.min(dayStart + DAY_SECONDS, opts.to);
420	    const stats = computeGroupSegment(group.versions, seriesByDevice, segStart, segEnd);
421	    days++;
422	
423	    const date = formatIsoUtc(dayStart).slice(0, 10);
424	    const dayIncomplete = stats.anomaly > 0 || stats.unknown > 0;
425	    if (dayIncomplete) incomplete = true;
426	
427	    let consumption: string;
428	    if (stats.valid > 0) {
429	      consumption = `consumption=${formatKwh(stats.consumption)} kWh (estimate)`;
430	      total += stats.consumption;
431	      computedDays++;
432	    } else {
433	      consumption = 'consumption=n/a (no valid coverage)';
434	    }
435	    let line =
436	      `  ${date}  ${consumption}` +
437	      `  valid=${stats.valid}s  anomaly=${stats.anomaly}s  unknown=${stats.unknown}s`;
438	    if (dayIncomplete) line += '  INCOMPLETE';
439	    console.log(line);
440	    for (const p of stats.periods) {
441	      const members = p.members === null ? '(no version in effect)' : p.members.join(',');
442	      console.log(
443	        `    members=${members}  period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`,
444	      );
445	    }
446	  }
447	
448	  const totalText =
449	    computedDays > 0
450	      ? `total consumption=${formatKwh(total)} kWh (estimate)`
451	      : 'total consumption=n/a (no valid coverage)';
452	  const status = incomplete
453	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
454	    : 'status=complete';
455	  console.log(
456	    `  summary: group=${group.id}  computed=${computedDays}/${days} day(s)  ${totalText}  ${status}`,
457	  );
458	  return 0;
459	}
