122	    if (!ok) throw bad('invalid rule entry');
123	    if (ruleIds.has(r.id as string)) throw bad(`duplicate rule id '${r.id}'`);
124	    ruleIds.add(r.id as string);
125	    rules.push({ id: r.id as string, device: r.device as string, thresholdMilli: thresholdMilli as bigint });
126	  }
127	
128	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
129	  const alertIds = new Set<string>();
130	  for (const a of o.alerts as Array<Record<string, unknown>>) {
131	    const ok =
132	      a !== null &&
133	      typeof a === 'object' &&
134	      typeof a.id === 'string' &&
135	      a.id.length > 0 &&
136	      typeof a.ruleId === 'string' &&
137	      ruleIds.has(a.ruleId) &&
138	      typeof a.date === 'string' &&
139	      DATE_RE.test(a.date) &&
140	      (a.status === 'triggered' || a.status === 'recovered') &&
141	      typeof a.acknowledged === 'boolean' &&
142	      Array.isArray(a.events);
143	    if (!ok) throw bad('invalid alert entry');
144	    if (alertIds.has(a.id as string)) throw bad(`duplicate alert id '${a.id}'`);
145	    alertIds.add(a.id as string);
146	    for (const e of a.events as Array<Record<string, unknown>>) {
147	      const eok =
148	        e !== null &&
149	        typeof e === 'object' &&
150	        Number.isSafeInteger(e.seq) &&
151	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
152	        (e.consumptionMilli === undefined ||
153	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
154	      if (!eok) throw bad('invalid alert event');
155	    }
156	  }
157	  return {
158	    nextAlertNum: o.nextAlertNum as number,
159	    nextEventSeq: o.nextEventSeq as number,
160	    rules,
161	    alerts: o.alerts as unknown as AlertRecord[],
162	  };
163	}
164	
165	/** 原子写入告警存储;失败抛错,原有数据保持不变。 */
166	function saveAlertState(path: string, state: AlertState): void {
167	  mkdirSync(dirname(path), { recursive: true });
168	  const tmp = `${path}.tmp-${process.pid}`;
169	  const body =
170	    JSON.stringify(
171	      {
172	        version: 1,
173	        ...state,
174	        rules: state.rules.map((r) => ({ ...r, thresholdMilli: r.thresholdMilli.toString() })),
175	      },
176	      null,
177	      2,
178	    ) + '\n';
179	  try {
180	    writeFileSync(tmp, body, 'utf8');
181	    renameSync(tmp, path);
182	  } catch (e) {
183	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
184	  }
185	}
186	
187	/**
188	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
189	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
190	 */
191	function deviceSeries(device: string): Reading[] {
192	  const all = loadStore(dataFilePath());
193	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
194	  for (let i = 1; i < series.length; i++) {
195	    if (series[i].ts === series[i - 1].ts) {
196	      throw new StoreError(
197	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
198	      );
199	    }
200	  }
201	  return series;
202	}
203	
204	/** 不可判定原因(未知/异常覆盖秒数)。 */
205	function undecidableReason(stats: { unknown: number; anomaly: number }): string {
206	  return `undecidable (unknown=${stats.unknown}s anomaly=${stats.anomaly}s)`;
207	}
208	
209	/**
210	 * 创建规则。相同标识等价参数(同设备、同阈值)重试成功且不重复创建;
211	 * 异参重试报冲突。设备必须已有存储读数。返回进程退出码。
212	 */
213	export function cmdRuleCreate(opts: {
214	  id: string;
215	  device: string;
216	  thresholdMilli: bigint;
217	}): number {
218	  const statePath = alertFilePath();
219	  let state: AlertState;
220	  try {
221	    state = loadAlertState(statePath);
222	  } catch (e) {
223	    if (e instanceof StoreError) {
224	      err(e.message);
225	      return 1;
226	    }
227	    throw e;
228	  }
229	
230	  const existing = state.rules.find((r) => r.id === opts.id);
231	  if (existing) {
232	    if (existing.device === opts.device && existing.thresholdMilli === opts.thresholdMilli) {
233	      console.log(
234	        `rule '${opts.id}' already exists with identical parameters (device=${existing.device} threshold=${formatKwh(existing.thresholdMilli)} kWh); unchanged`,
235	      );
236	      return 0;
237	    }
238	    err(
239	      `rule '${opts.id}' already exists with different parameters ` +
240	        `(stored device=${existing.device} threshold=${formatKwh(existing.thresholdMilli)} kWh, ` +
241	        `got device=${opts.device} threshold=${formatKwh(opts.thresholdMilli)} kWh); conflict`,
242	    );
243	    return 1;
244	  }
245	
246	  let devices: Set<string>;
247	  try {
248	    devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
249	  } catch (e) {
250	    if (e instanceof StoreError) {
251	      err(e.message);
252	      return 1;
253	    }
254	    throw e;
255	  }
256	  if (!devices.has(opts.device)) {
257	    err(`unknown device '${opts.device}': no stored readings; import readings before creating a rule`);
258	    return 1;
259	  }
260	
261	  state.rules.push({ id: opts.id, device: opts.device, thresholdMilli: opts.thresholdMilli });
262	  try {
263	    saveAlertState(statePath, state);
264	  } catch (e) {
265	    if (e instanceof StoreError) {
266	      err(e.message);
267	      return 1;
268	    }
269	    throw e;
270	  }
271	  console.log(
272	    `rule '${opts.id}' created: device=${opts.device} threshold=${formatKwh(opts.thresholdMilli)} kWh`,
273	  );
274	  return 0;
275	}
276	
277	/** 列出全部规则。只读。返回进程退出码。 */
278	export function cmdRuleList(): number {
279	  let state: AlertState;
280	  try {
281	    state = loadAlertState(alertFilePath());
282	  } catch (e) {
283	    if (e instanceof StoreError) {
284	      err(e.message);
285	      return 1;
286	    }
287	    throw e;
288	  }
289	  if (state.rules.length === 0) {
290	    console.log('no rules defined');
291	    return 0;
292	  }
293	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
294	  for (const r of rules) {
295	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
296	    console.log(
297	      `rule ${r.id}  device=${r.device}  threshold=${formatKwh(r.thresholdMilli)} kWh  open alerts=${open}`,
298	    );
299	  }
300	  return 0;
301	}
302	
303	/**
304	 * 评估规则在连续完整 UTC 日期范围 [from, to) 上的超限情况。
305	 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交。
306	 * 返回进程退出码。
307	 */
308	export function cmdEvaluate(opts: { ruleId: string; from: number; to: number }): number {
309	  const statePath = alertFilePath();
310	  let state: AlertState;
311	  let rule: AlertRule;
312	  let series: Reading[];
313	  try {
314	    state = loadAlertState(statePath);
315	    const found = state.rules.find((r) => r.id === opts.ruleId);
316	    if (!found) {
317	      err(`unknown rule '${opts.ruleId}'`);
318	      return 1;
319	    }
320	    rule = found;
321	    series = deviceSeries(rule.device);
322	  } catch (e) {
323	    if (e instanceof StoreError) {
324	      err(e.message);
325	      return 1;
326	    }
327	    throw e;
328	  }
329	
330	  const threshold = rule.thresholdMilli;
331	  const lines: string[] = [];
332	  for (let dayStart = opts.from; dayStart < opts.to; dayStart += DAY_SECONDS) {
333	    const date = formatIsoUtc(dayStart).slice(0, 10);
334	    const stats = computeDay(series, dayStart, dayStart + DAY_SECONDS);
335	    if (stats.unknown > 0 || stats.anomaly > 0) {
336	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
337	      lines.push(`  ${date}  ${undecidableReason(stats)}  no alert action`);
338	      continue;
339	    }
340	    const exceeded = stats.consumption > threshold;
341	    const cmp =
342	      `consumption=${formatKwh(stats.consumption)} kWh ` +
343	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
344	    const open = state.alerts.find(
345	      (a) => a.ruleId === rule.id && a.date === date && a.status === 'triggered',
346	    );
347	    if (exceeded) {
348	      if (open) {
349	        // 重复超限:保留原标识,不新增事件。
350	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered`);
351	      } else {
352	        const id = `alert-${state.nextAlertNum++}`;
353	        state.alerts.push({
354	          id,
355	          ruleId: rule.id,
356	          date,
357	          status: 'triggered',
358	          acknowledged: false,
359	          events: [
360	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
361	          ],
362	        });
363	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)`);
364	      }
365	    } else {
366	      if (open) {
367	        open.status = 'recovered';
368	        open.events.push({
369	          seq: state.nextEventSeq++,
370	          type: 'recovered',
371	          consumptionMilli: stats.consumption.toString(),
372	        });
373	        lines.push(`  ${date}  ${cmp}  NORMAL  alert ${open.id} recovered`);
374	      } else {
375	        lines.push(`  ${date}  ${cmp}  NORMAL  no alert`);
376	      }
377	    }
378	  }
379	
380	  try {
381	    saveAlertState(statePath, state);
382	  } catch (e) {
383	    if (e instanceof StoreError) {
384	      err(e.message);
385	      return 1;
386	    }
387	    throw e;
388	  }
389	
390	  console.log(
391	    `rule: ${rule.id}  device=${rule.device}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
392	  );
393	  for (const line of lines) console.log(line);
394	  return 0;
395	}
396	
397	/**
398	 * 查询规则的告警历史。只读,不修改数据。
399	 * 给定日期范围时逐日展示消耗或不可判定原因及各次告警;省略范围时展示
400	 * 有告警记录的全部日期。返回进程退出码。
401	 */
402	export function cmdAlerts(opts: { ruleId: string; from?: number; to?: number }): number {
403	  let state: AlertState;
404	  let rule: AlertRule;
405	  let series: Reading[];
406	  try {
407	    state = loadAlertState(alertFilePath());
408	    const found = state.rules.find((r) => r.id === opts.ruleId);
409	    if (!found) {
410	      err(`unknown rule '${opts.ruleId}'`);
411	      return 1;
412	    }
413	    rule = found;
414	    series = deviceSeries(rule.device);
415	  } catch (e) {
416	    if (e instanceof StoreError) {
417	      err(e.message);
418	      return 1;
419	    }
420	    throw e;
421	  }
422	
423	  let dayStarts: number[];
424	  if (opts.from !== undefined && opts.to !== undefined) {
425	    dayStarts = [];
426	    for (let d = opts.from; d < opts.to; d += DAY_SECONDS) dayStarts.push(d);
427	  } else {
428	    const dates = [
429	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
430	    ].sort();
431	    dayStarts = dates.map((d) => parseIso8601(`${d}T00:00:00Z`) as number);
432	  }
433	
434	  console.log(
435	    `rule: ${rule.id}  device=${rule.device}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
436	  );
437	  if (dayStarts.length === 0) {
438	    console.log(`  no alerts recorded for rule '${rule.id}'`);
439	    return 0;
440	  }
441	
442	  const threshold = rule.thresholdMilli;
443	  for (const dayStart of dayStarts) {
444	    const date = formatIsoUtc(dayStart).slice(0, 10);
445	    const stats = computeDay(series, dayStart, dayStart + DAY_SECONDS);
446	    if (stats.unknown > 0 || stats.anomaly > 0) {
447	      console.log(`  ${date}  ${undecidableReason(stats)}`);
448	    } else {
449	      const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
450	      console.log(
451	        `  ${date}  consumption=${formatKwh(stats.consumption)} kWh ` +
452	          `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)`,
453	      );
454	    }
455	    const alerts = state.alerts
456	      .filter((a) => a.ruleId === rule.id && a.date === date)
457	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
458	    if (alerts.length === 0) {
459	      console.log('    no alerts');
460	      continue;
461	    }
462	    for (const a of alerts) {
463	      console.log(
464	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
465	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
466	      );
467	      const events = a.events
468	        .map((e) => {
469	          const consumption =
470	            e.consumptionMilli !== undefined
471	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
472	              : '';
473	          return `#${e.seq} ${e.type}${consumption}`;
474	        })
475	        .join(', ');
476	      console.log(`      events: ${events}`);
477	    }
478	  }
479	  return 0;
480	}
481	
482	/**
483	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
484	 * 确认不改变超限或恢复状态。返回进程退出码。
485	 */
486	export function cmdAck(alertId: string): number {
487	  const statePath = alertFilePath();
488	  let state: AlertState;
489	  try {
490	    state = loadAlertState(statePath);
491	  } catch (e) {
492	    if (e instanceof StoreError) {
493	      err(e.message);
494	      return 1;
495	    }
496	    throw e;
497	  }
498	  const alert = state.alerts.find((a) => a.id === alertId);
499	  if (!alert) {
500	    err(`unknown alert '${alertId}'`);
501	    return 1;
502	  }
503	  if (alert.acknowledged) {
504	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
505	    return 0;
506	  }
507	  alert.acknowledged = true;
508	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
509	  try {
510	    saveAlertState(statePath, state);
511	  } catch (e) {
512	    if (e instanceof StoreError) {
513	      err(e.message);
514	      return 1;
515	    }
516	    throw e;
517	  }
518	  console.log(
519	    `alert ${alert.id} acknowledged (rule=${alert.ruleId} date=${alert.date} status=${alert.status})`,
520	  );
521	  return 0;
522	}
