```ts
function loadAllSeriesChecked(): Map<string, Reading[]> {
  const all = loadStore(dataFilePath());
  const byDevice = new Map<string, Reading[]>();
  for (const r of all) {
    const list = byDevice.get(r.device);
    if (list) list.push(r);
    else byDevice.set(r.device, [r]);
  }
  for (const [device, list] of byDevice) {
    list.sort((a, b) => a.ts - b.ts);
    for (let i = 1; i < list.length; i++) {
      if (list[i].ts === list[i - 1].ts) {
        throw new StoreError(`storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`);
      }
    }
  }
  return byDevice;
}
