  const id = r.id as string;
  if (ruleIds.has(id)) throw bad(`duplicate rule id '${id}'`);
  ruleIds.add(id);
  rules.push({
    id,
    targetType: hasDevice ? 'device' : 'group',
    target: target as string,
    thresholdMilli: thresholdMilli as bigint,
  });
}

